fn obj2sctype(rep: NumpyObject, default: Option<NumpyScalarType>) -> Option<NumpyScalarType> {
    match rep {
        NumpyObject::Integer(_)        => Some(NumpyScalarType::Int64),
        NumpyObject::Float(_)          => Some(NumpyScalarType::Float64),
        NumpyObject::IntArray(_)       => Some(NumpyScalarType::Int64),
        NumpyObject::FloatArray(_)     => Some(NumpyScalarType::Float64),
        NumpyObject::ComplexArray(_)   => Some(NumpyScalarType::Complex128),
        NumpyObject::StringValue(_)    => Some(NumpyScalarType::String),
        NumpyObject::BooleanValue(_)   => Some(NumpyScalarType::Bool),
        NumpyObject::GenericObject(_)  => default,
    }
}